create table if not exists public.financing_simulations(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),profile_id uuid not null references public.buyer_profiles(id) on delete cascade,reference text unique not null,session_id uuid not null,submission_hash text unique not null,project_type text not null,purchase_mode text not null,income_1 integer not null check(income_1>=0),income_2 integer not null default 0 check(income_2>=0),charges integer not null default 0 check(charges>=0),contribution integer not null default 0 check(contribution>=0),duration_years integer not null check(duration_years between 1 and 40),employment_1 text not null,employment_2 text,property_found text not null,property_price bigint,estimated_payment integer not null,estimated_borrowing bigint not null,estimated_budget_min bigint not null,estimated_budget bigint not null,estimated_budget_max bigint not null,calculation_config jsonb not null default '{}',source text not null default 'financing_funnel');
create table if not exists public.financing_consents(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),simulation_id uuid not null references public.financing_simulations(id) on delete cascade,profile_id uuid not null references public.buyer_profiles(id) on delete cascade,kind text not null check(kind in('privacy','minitaux_referral')),granted boolean not null,text_version text not null,granted_at timestamptz,unique(simulation_id,kind));
create table if not exists public.financing_referrals(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),simulation_id uuid not null unique references public.financing_simulations(id) on delete cascade,profile_id uuid not null references public.buyer_profiles(id),consent_id uuid not null references public.financing_consents(id),broker_name text not null default 'Sulivan Langa-Mora — MiNiTAUX',status text not null default 'pending_manual' check(status in('pending_manual','submitted','accepted','in_progress','successful','unsuccessful','failed')),actelo_reference text,submitted_at timestamptz,last_error text);
create table if not exists public.financing_service_tasks(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),simulation_id uuid not null references public.financing_simulations(id) on delete cascade,kind text not null check(kind in('declare_actelo','sync_kw_impact','callback')),status text not null default 'pending' check(status in('pending','in_progress','completed','failed')),payload jsonb not null default '{}',completed_at timestamptz);
create index if not exists financing_profile_idx on public.financing_simulations(profile_id,created_at desc);create index if not exists financing_referral_status_idx on public.financing_referrals(status,created_at desc);create index if not exists financing_task_status_idx on public.financing_service_tasks(status,kind);
alter table public.financing_simulations enable row level security;alter table public.financing_consents enable row level security;alter table public.financing_referrals enable row level security;alter table public.financing_service_tasks enable row level security;
create policy "buyer admins financing simulations" on public.financing_simulations for all to authenticated using(public.is_foncier_admin()) with check(public.is_foncier_admin());create policy "buyer admins financing consents" on public.financing_consents for all to authenticated using(public.is_foncier_admin()) with check(public.is_foncier_admin());create policy "buyer admins financing referrals" on public.financing_referrals for all to authenticated using(public.is_foncier_admin()) with check(public.is_foncier_admin());create policy "buyer admins financing tasks" on public.financing_service_tasks for all to authenticated using(public.is_foncier_admin()) with check(public.is_foncier_admin());
